CREATE TABLE supplier_payments(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,payment_code VARCHAR(30) NOT NULL,supplier_invoice_id BIGINT UNSIGNED NOT NULL,vendor_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(18,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,reference VARCHAR(190) NULL,notes TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',invoice_code_snapshot VARCHAR(30) NULL,invoice_number_snapshot VARCHAR(100) NULL,vendor_code_snapshot VARCHAR(30) NULL,vendor_name_snapshot VARCHAR(190) NULL,project_code_snapshot VARCHAR(30) NULL,project_name_snapshot VARCHAR(190) NULL,invoice_total_snapshot DECIMAL(18,2) NULL,previous_paid_snapshot DECIMAL(18,2) NULL,remaining_payable_snapshot DECIMAL(18,2) NULL,created_by BIGINT UNSIGNED NOT NULL,posted_at DATETIME NULL,posted_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_supplier_payments_code(payment_code),KEY idx_supplier_payments_history(supplier_invoice_id,payment_date,id),KEY idx_supplier_payments_filters(status,payment_method,payment_date),CONSTRAINT fk_supplier_payments_invoice FOREIGN KEY(supplier_invoice_id) REFERENCES supplier_invoices(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_payments_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_payments_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_payments_created FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_payments_posted FOREIGN KEY(posted_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_payments_cancelled FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_supplier_payments_amount CHECK(amount>0),CONSTRAINT chk_supplier_payments_method CHECK(payment_method IN('cash','bank_transfer','cheque','other')),CONSTRAINT chk_supplier_payments_status CHECK(status IN('draft','posted','cancelled')),CONSTRAINT chk_supplier_payments_audit CHECK((status='draft' AND posted_at IS NULL AND posted_by IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND invoice_total_snapshot IS NULL AND previous_paid_snapshot IS NULL AND remaining_payable_snapshot IS NULL) OR(status='posted' AND posted_at IS NOT NULL AND posted_by IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND invoice_code_snapshot IS NOT NULL AND vendor_name_snapshot IS NOT NULL AND project_name_snapshot IS NOT NULL AND invoice_total_snapshot IS NOT NULL AND previous_paid_snapshot IS NOT NULL AND remaining_payable_snapshot IS NOT NULL) OR(status='cancelled' AND posted_at IS NULL AND posted_by IS NULL AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL AND invoice_total_snapshot IS NULL AND previous_paid_snapshot IS NULL AND remaining_payable_snapshot IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
